// Offline-first service worker. manifest.json (generated by scripts/build.py) lists every file.
//  - "app" files:     cache named by content hash; replaced atomically on a new deploy
//  - "pyodide" files: cache named by Pyodide version; ~13 MB, survives app updates (downloaded once)
const MANIFEST = "manifest.json";
const scope = self.registration.scope;
const abs = (p) => new URL(p, scope).href;

self.addEventListener("install", (e) => e.waitUntil((async () => {
  const m = await (await fetch(MANIFEST, { cache: "no-store" })).json();
  const app = await caches.open(`app-${m.version}`);
  await app.addAll([...m.app, ...m.wheels, MANIFEST].map((u) => new Request(abs(u), { cache: "reload" })));
  const py = await caches.open(`pyodide-${m.pyodide.version}`);
  const have = new Set((await py.keys()).map((r) => r.url));
  await Promise.all(m.pyodide.files.map(abs).filter((u) => !have.has(u)).map((u) => py.add(new Request(u, { cache: "reload" }))));
  await self.skipWaiting();                  // only reached once EVERYTHING is cached -> never a half-installed app
})()));

self.addEventListener("activate", (e) => e.waitUntil((async () => {
  const m = await (await caches.match(abs(MANIFEST))).json();
  const keep = new Set([`app-${m.version}`, `pyodide-${m.pyodide.version}`]);
  for (const k of await caches.keys()) if (!keep.has(k)) await caches.delete(k);
  await self.clients.claim();
})()));

// Strategy: the big, versioned Pyodide files are cache-first. Everything else (our small app files) is NETWORK-FIRST with a
// short timeout and falls back to the cache, so an online reload always shows the newest build, and offline/flaky networks
// still work. (Pure cache-first made users look at a stale build until a second reload.)
const timeout = (ms) => new Promise((_, rej) => setTimeout(() => rej(new Error("timeout")), ms));
async function appCache() { const k = (await caches.keys()).filter((n) => n.startsWith("app-")); return caches.open(k[k.length - 1]); }

self.addEventListener("fetch", (e) => {
  const req = e.request, url = new URL(req.url);
  if (req.method !== "GET" || url.origin !== location.origin) return;     // api.github.com etc: never cached
  e.respondWith((async () => {
    const cached = () => caches.match(req, { ignoreSearch: true }).then((h) => h || (req.mode === "navigate" ? caches.match(abs("index.html")) : undefined));
    if (url.pathname.includes("/vendor/pyodide/")) return (await cached()) || fetch(req);
    try {
      const res = await Promise.race([fetch(req, { cache: "no-cache" }), timeout(4000)]);   // revalidate with the server
      if (res.ok && !url.pathname.endsWith("/sw.js")) appCache().then((c) => c.put(req, res.clone())).catch(() => {});
      return res;
    } catch {
      return (await cached()) || Response.error();
    }
  })());
});
